          code: "import math\n\ndef ftcs_heat(r, steps, n=10):\n    dx = 1.0 / n\n    dt = r * dx * dx          # a^2 = 1\n    u = [4.0 * (j * dx) * (1.0 - j * dx) for j in range(n + 1)]\n    hist = [u[:]]\n    for _ in range(steps):\n        w = u[:]\n        for j in range(1, n):\n            w[j] = u[j] + r * (u[j + 1] - 2.0 * u[j] + u[j - 1])\n        u = w\n        hist.append(u[:])\n    return hist, dt\n\ndef exact_heat(x, t):\n    s = 0.0\n    for k in range(0, 60):\n        m = 2 * k + 1\n        s += (32.0 / (m * math.pi) ** 3) * math.sin(m * math.pi * x) * math.exp(-m * m * math.pi * math.pi * t)\n    return s\n\nfor r in (0.5, 1.0):\n    hist, dt = ftcs_heat(r, 7)\n    tag = 'stable' if r <= 0.5 else 'UNSTABLE'\n    print('r = %.2f (dt = %.4f, %s)' % (r, dt, tag))\n    print('  %3s %8s %10s %10s %10s' % ('n', 't', 'u(0.5)', 'max|u|', 'min u'))\n    for n, u in enumerate(hist):\n        print('  %3d %8.3f %10.5f %10.5f %10.5f' % (n, n * dt, u[5], max(abs(v) for v in u), min(u)))\n    print('')\n\nprint('与精确解比较（r = 0.5，x = 0.5）：')\nhist, dt = ftcs_heat(0.5, 7)\nfor n in (1, 2, 4, 7):\n    t = n * dt\n    print('  n = %d, t = %.3f: 数值 = %.6f, 精确 = %.6f, 相对误差 = %+.3f%%' % (n, t, hist[n][5], exact_heat(0.5, t), (hist[n][5] / exact_heat(0.5, t) - 1.0) * 100.0))\n\nprint('')\nprint('CFL 最大时间步（热方程，r <= 0.5）：')\nfor dx, a2 in ((0.1, 1.0), (0.2, 0.5), (0.25, 2.0), (0.05, 1.0)):\n    print('  dx = %.2f, a^2 = %.2f -> dt <= %.6f' % (dx, a2, 0.5 * dx * dx / a2))\n",
